import React, { createContext, useReducer } from 'react';

export const CartContext = createContext();

const initialState = { items: [], total: 0 };

function cartReducer(state, action) {
    switch (action.type) {
        case 'ADD':
            const exists = state.items.find(i => i._id === action.payload._id);
            const updatedItems = exists
                ? state.items.map(i =>
                    i._id === action.payload._id
                        ? { ...i, quantity: i.quantity + 1 }
                        : i
                )
                : [...state.items, { ...action.payload, quantity: 1 }];
            return {
                items: updatedItems,
                total: updatedItems.reduce((sum, i) => sum + i.quantity * i.currentPrice, 0)
            };
        case 'REMOVE':
            const filtered = state.items.filter(i => i._id !== action.payload);
            return {
                items: filtered,
                total: filtered.reduce((sum, i) => sum + i.quantity * i.currentPrice, 0)
            };
        case 'UPDATE':
            const changed = state.items.map(i =>
                i._id === action.payload._id
                    ? { ...i, quantity: action.payload.quantity }
                    : i
            );
            return {
                items: changed,
                total: changed.reduce((sum, i) => sum + i.quantity * i.currentPrice, 0)
            };
        case 'CLEAR':
            return initialState;
        default:
            return state;
    }
}

export const CartProvider = ({ children }) => {
    const [state, dispatch] = useReducer(cartReducer, initialState);
    return (
        <CartContext.Provider value={{ cart: state, dispatch }}>
            {children}
        </CartContext.Provider>
    );
};
